<?php
require_once __DIR__.'/../includes/auth.php';require_login();
$q=trim((string)($_GET['q']??''));$uid=filter_input(INPUT_GET,'unit_id',FILTER_VALIDATE_INT);$sid=filter_input(INPUT_GET,'subject_id',FILTER_VALIDATE_INT);$medium=(string)(user()['medium']??'English');
$sql="SELECT l.*,s.name_en,s.name_si,s.name_ta,u.unit_number FROM lessons l JOIN subjects s ON s.id=l.subject_id JOIN units u ON u.id=l.unit_id WHERE l.grade_id=? AND l.status='active' AND l.content_source='textbook' AND (l.medium='All' OR l.medium=?)";$types='is';$args=[user()['grade_id'],$medium];
if($uid){$sql.=' AND l.unit_id=?';$types.='i';$args[]=$uid;}if($sid){$sql.=' AND l.subject_id=?';$types.='i';$args[]=$sid;}
if($q!==''){$col=$_SESSION['lang']??'en';$sql.=" AND (l.title_$col LIKE ? OR l.summary_$col LIKE ? OR l.key_terms_$col LIKE ?)";$like='%'.$q.'%';$types.='sss';array_push($args,$like,$like,$like);}
$sql.=' ORDER BY s.name_en,u.display_order,l.display_order';$s=db()->prepare($sql);$s->bind_param($types,...$args);$s->execute();$pageTitle=tr('lessons');include __DIR__.'/../includes/header.php';
?><h1><?=tr('lessons')?></h1><form class="card"><input name="q" value="<?=e($q)?>" placeholder="Search lessons"><button>Search</button><?php if($sid):?><input type="hidden" name="subject_id" value="<?=intval($sid)?>"><?php endif;?></form><?php $res=$s->get_result();if(!$res->num_rows):?><div class="card muted">No matching textbook lessons found for <?=e($medium)?> medium.</div><?php endif;while($r=$res->fetch_assoc()):?><a class="card" style="display:block;text-decoration:none;color:inherit" href="lesson.php?id=<?=intval($r['id'])?>"><span class="badge"><?=e(locale_value($r,'name'))?> · Lesson <?=intval($r['unit_number'])?></span><h2><?=e(locale_value($r,'title'))?></h2><p><?=e(locale_value($r,'short_description'))?></p></a><?php endwhile;include __DIR__.'/../includes/footer.php';
